  "settings.integratedTerminalShell": "Оболонка вбудованого термінала",
  "settings.integratedTerminalShellDescription":
    "Застосовується лише до нових сеансів. У Windows цю оболонку використовує Bash; режим «Авто» спершу пробує Git Bash, потім cmd.exe.",
  "settings.integratedTerminalShell.auto": "Авто",
  "settings.nativeSearchEnhancements": "Розширені Find і Grep",
  "settings.nativeSearchEnhancementsDescription":
    "Використовувати розширені Find і Grep у нових сеансах і сеансах, відновлених після перезапуску застосунку. Активні сеанси зберігають поточне налаштування; у Windows Find не змінюється.",
  "settings.memory": "Пам'ять",
  "settings.memory.workspaceMemory": "Пам'ять робочого простору",
  "settings.memory.indexAsContext": "Вставляти пам'ять як контекст",
  "settings.memory.indexAsContextDescription":
    "Усталено індекс пам'яті вставляється разом з інструкціями робочого простору та може конкурувати з ними. Якщо увімкнено, пам'ять чітко позначається як фоновий контекст: безпечніше для застарілих нотаток і вбудованого вмісту, але може дотримуватися дещо менш суворо.",
  "settings.memoryDescription":
    "Зберігати й повторно використовувати довгостроковий контекст у робочих просторах. Застосовується до нових сеансів і може збільшити кількість запитів до моделі та витрати токенів.",
