  "settings.autoDownloadAndInstallUpdates": "Автоматично завантажувати та встановлювати оновлення",
  "settings.autoDownloadAndInstallUpdatesDescription":
    "Якщо ввімкнено, оновлення почне завантажуватися одразу після виявлення. Якщо виконуються завдання, перезапуск однаково потребуватиме підтвердження.",
